import React, { useEffect, useState, useRef } from "react";

// import { PDFDocument, StandardFonts, rgb } from 'pdf-lib'

import { getStore, updStore, gen16CodeId, ObjectKeys, parseFloatToDecimal, parseDate,  copyToClipboard, qryStore, fetchEncryptStream } from "../../../stores/Utils";

import {  SvgIcon_Cmpt, AccountLabelDetail_Cmpt, CheckBoxSlide_Cmpt } from "../../../components";


import "./styles.css"

import { useNavigate } from "react-router";

import { InventoryLabelsPdf, InventoryLabelsPdf1X3 } from "../services/export_service";
import { getall_subaccount } from "../../CuentasContables/services/server_fetching";
import { getall_provider } from "../../ProvidersCustomers/services/server_fetching";
import { entry_invoice_acc_2, get_inventory_invoice, getall_product } from "../services/server_fetching";
import { CloseModal } from "../../../components/DialogHRM";
import { OpenToast } from "../../../components/Toast";
import { NavLink } from "react-router-dom";





const Svg = SvgIcon_Cmpt();


const AccountLabelDetail = AccountLabelDetail_Cmpt();

const CheckBoxSlide = CheckBoxSlide_Cmpt();

const frmNm = "view_product_mov"

const ViewMovement  = ({ data, confirm, item }) => {
	const [initialize, setInitialize] = useState(false);
	const [, set_obs] = useState(0);
	const [prov, setProv] = useState(null);

	const navigate = useNavigate();



	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			updStore("accountPicker", {});
			set_obs(gen16CodeId())

			if(!getStore("account_ids")){
				getall_subaccount(updObs);
			}
			if(!getStore("providers_ids")?.[ item?.providerId]?.name){
				getall_provider(updObs)
			}
			if(!getStore("products_ids")){
				getall_product(updObs)
			}
			
			
		}
		item?.entriesInvoiceId && search_movement(item?.entriesInvoiceId, updObs)
	},[item.providerId, item?.entriesInvoiceId, initialize]);


	const updObs  = async ()  => {
		set_obs(gen16CodeId())
	};

	const handleClose =  (td) => {

		confirm && confirm();
		data.modalID && CloseModal({id:data.modalID});
		td.data.comprobanteId && 
		navigate({
			pathname: "/accounting-ledger" ,
			search: `?cId=${td.data.comprobanteId}`
		});
    }


	

	 const search_movement = async (id, cb) => {
		// 11-X17453
		
		let bdyq2 = {...getStore(qryStore())?.find_entry_invoice};
		bdyq2.params = {
			businessId:  getStore("profileUser")?.businessId,
			"entriesInvoiceId": id
		}
		if(id){
			
			const res = fetchEncryptStream(bdyq2);
			const td = await res;
			if (td?.providerId ) {
				setProv(getStore("providers_ids")?.[td?.providerId]?.name)
				cb && cb();
			}
		}
	};

	const send2Accountant  = async ()  => {
		entry_invoice_acc_2( item?.entriesInvoiceId,handleClose);
	};

	const clearComp  = async ()  => {
		// clearComprobante( item?.entriesInvoiceId,updObs);
	};
	
	// let customer = getStore("providers_ids")?.[ item?.providerId]?.name;
	
	
	const copyToClpbCB  =  ()  => {
		//OpenToast({ text: "Copied to clipobard", timeout: 1500 });
	};

	const copyToClpb  =  (v)  => {
		copyToClipboard( v,copyToClpbCB);
	};

	
	const closeCG2V  =  ()  => {
		data.modalID && CloseModal({id:data.modalID});
	};
			
	
	return (
		<div style={{
			maxHeight: "90vh",
			minHeight:  "58vh",
			width: "860px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px"
		}}>
			<div className="_dsplFlx ">
				<p className="form_title">
				{ item.amount<0? "Salida": "Entrada"} de Mercancias
				</p>
				<div className="flexSpace"/>
				<div>

					<div className="date2Upd" >
						{ parseDate(item?.date)}
					</div>
				</div>
			</div>

			<div className="_dsplFlx ">
				
				<div className="_dsplFlx ">
					<div className="flexSpace"/>
					{item?.["comprobanteId"]?
						<div className=" "  onClick={clearComp}>
							<p className="label">
								{"Comprobante"}
							</p>
						
								<NavLink to={{
										pathname: "/accounting-ledger" ,
										search: `?cId=${item?.["comprobanteId"]}`
									}}>
										<div className="date2Upd" onClick={closeCG2V}>

											{ item?.["comprobanteId"]}
										</div>
								</NavLink>
						</div>:
						<p className="group_title addBtn purple" >
							Enviar a contabilidad
						</p>
					}
				</div>
				<div className="flexSpace"/>
				<div>
					<p className="label">
						{"Documento"}
					</p>
					<div className="date2Upd" onClick={()=>copyToClpb(item?.["document"])} >
						{ item?.["document"]}
					</div>
				</div>
			</div>

			
			<ProductsBox 
				data={item.products} 
				entriesInvoiceId={item?.entriesInvoiceId}
				prov={prov}
			/>

			
			<div className="_dsplFlx " style={{margin: "4px 1px 5px 10px"}}>
				<div className="flexSpace"/>
				<div className="date2Upd" style={{margin: "0px 7px"}}>
					Balance:
				</div>
				${ item.amount.toFixed(2)}
			</div>
		

			
		</div>
	);
};

export default ViewMovement;





const EstaCuadrado = (obj) => {
	let balance = 0;
	let arr = obj && ObjectKeys(obj);
	arr && arr?.map((element, indE)=>{
		let data = obj[element];
		let newB = balance.toFixed(2);
		let amount = data?.amount ? data?.type === "debit" ?  parseFloat(data.amount) :parseFloat(data.amount) *-1  : 0;
		balance = amount + parseFloat(newB);
		
	});
	return arr && arr?.length>0 && balance === 0;
}  







